#include "stdafx.h"#include "H_Class.h"static SBlockCreate MIN( "MIN", SH_MIN::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_MIN,W_MIN,51)void SH_MIN::InitParm(){#include "Blocks/MIN.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/MIN_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class MIN_IMPL : public W_MIN{public:  void StepT( SStepCalcParams &dt );};void SH_MIN::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  MIN_IMPL *impl = reinterpret_cast<MIN_IMPL*>(W);  impl->StepT( dt );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void MIN_IMPL::StepT( SStepCalcParams &dt ){  double r = NaN;  for( int i=1; i<(NUMOFINPUTS+1); ++i )  {    if( IsNaN(IN[i]) )      continue;    if( IsNaN(r) )      r = IN[i];    r = __min( r, IN[i] );  }  OUT = r;}